window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-38f41f8dba2bbde2"]={"versions": [{"id": "FIG-38f41f8dba2bbde2", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematische Struktur- und Speicherlayout-Darstellung von Hardware-Objekten (Mailboxen) im AUTOSAR CAN-Treiber (CanDriver, BSW). Das Diagramm veranschaulicht die Anordnung von Hardware-Objekten im Controller-Speicher bzw. deren Zuordnung zu Hardware Handles (HTH/HRH).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine Tabelle aus acht identisch aufgebauten Zeilen (Hardware-Objekte), jeweils unterteilt in drei Segmente bzw. Felder je Objekt. Links neben jeder Zeile befindet sich eine horizontale Referenzlinie (Zuordnungsanzeige für Hardware Handles wie HRH oder HTH). Über dem gesamten Block der Hardware-Objekte fasst eine geschweifte Klammer die Speicherstruktur zusammen. Beschriftungen innerhalb der Tabellenzellen fehlen in dieser Fassung.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Speicher- und Zuordnungsdarstellung ohne zeitliche Ablauf- oder Sequenzpfade. Jedes Hardware-Objekt dient als Hardware-Puffer für Sende- oder Empfangsbearbeitung im CAN-Controller.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Konzeptionelles Schaubild zur Veranschaulichung der Speicherorganisation von Hardware-Objekten im CAN-Controller. Da textliche Identifikatoren und Feldtypen innerhalb der Zellen nicht spezifiziert sind, dient die Darstellung als abstrakte Schablone für Pufferstrukturen und deren Handle-Referenzierung.</p>"}, {"id": "FIG-7e1068363dfd313a", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematische Struktur- und Speicherlayout-Darstellung von Hardware-Objekten (Mailboxen) im AUTOSAR CAN-Treiber (CanDriver, BSW). Das Diagramm veranschaulicht die Anordnung von Hardware-Objekten im Controller-Speicher bzw. deren Zuordnung zu Hardware Handles (HTH/HRH).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine Tabelle aus acht Zeilen, die Hardware-Objekte des CAN-Controllers repräsentieren. Jedes Hardware-Objekt ist in drei Spalten gegliedert:</p>\n<ul class=\"fig-list\">\n<li><code>ID</code>: CAN-Identifier (Nachrichten-ID / Filter-ID)</li>\n<li><code>DLC</code>: Data Length Code (Längenangabe)</li>\n<li><code>SDU</code>: Service Data Unit (Nutzdaten-Payload)</li>\n</ul>\n<p class=\"fig-p\">Links neben jeder Zeile verweist eine horizontale Referenzlinie auf die Zuordnung zu Hardware Handles (HRH bzw. HTH). Eine übergeordnete geschweifte Klammer überspannt alle acht Hardware-Objekte.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Speicher- und Zuordnungsdarstellung ohne zeitliche Ablauf- oder Sequenzpfade. Jedes Hardware-Objekt dient als Hardware-Puffer für Sende- oder Empfangsbearbeitung im CAN-Controller.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert die Datenstruktur eines Hardware-Objekts im CAN-Hardware-Puffer. Jeder Pufferplatz setzt sich verbindlich aus Identifier (<code>ID</code>), Datenlängen-Information (<code>DLC</code>) und Nutzdatenbereich (<code>SDU</code>) zusammen und ist über zugeordnete Handles (HTH/HRH) durch den CAN-Treiber anzusprechen.</p>"}, {"id": "FIG-b0bd5dbaada32b7e", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Schematische Struktur- und Speicherlayout-Darstellung von Hardware-Objekten (Mailboxen) im AUTOSAR CAN-Treiber (CanDriver, BSW). Das Diagramm veranschaulicht die Anordnung von Hardware-Objekten im Controller-Speicher bzw. deren Zuordnung zu Hardware Handles (HTH/HRH).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine Tabelle aus acht Zeilen, die Hardware-Objekte des CAN-Controllers repräsentieren. Jedes Hardware-Objekt ist in drei Spalten gegliedert:</p>\n<ul class=\"fig-list\">\n<li><code>ID</code>: CAN-Identifier (Nachrichten-ID / Filter-ID)</li>\n<li><code>DLC</code>: Data Length Code (Längenangabe)</li>\n<li><code>SDU</code>: Service Data Unit (Nutzdaten-Payload)</li>\n</ul>\n<p class=\"fig-p\">Links neben jeder Zeile verweist eine horizontale Referenzlinie auf die Zuordnung zu Hardware Handles (HRH bzw. HTH). Eine übergeordnete geschweifte Klammer überspannt alle acht Hardware-Objekte.</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Speicher- und Zuordnungsdarstellung ohne zeitliche Ablauf- oder Sequenzpfade. Jedes Hardware-Objekt dient als Hardware-Puffer für Sende- oder Empfangsbearbeitung im CAN-Controller.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Spezifiziert die Datenstruktur eines Hardware-Objekts im CAN-Hardware-Puffer. Jeder Pufferplatz setzt sich verbindlich aus Identifier (<code>ID</code>), Datenlängen-Information (<code>DLC</code>) und Nutzdatenbereich (<code>SDU</code>) zusammen und ist über zugeordnete Handles (HTH/HRH) durch den CAN-Treiber anzusprechen.</p>"}], "trans": [{"from": "FIG-38f41f8dba2bbde2", "to": "FIG-7e1068363dfd313a", "fr": "R2.1.20", "tr": "R3.0.7", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Beschriftung der Speicherbereiche/Felder: Die acht Hardware-Objekt-Zeilen erhalten die explizite Aufteilung und Feldbezeichnung in <code>ID</code> (CAN-Identifier), <code>DLC</code> (Data Length Code) und <code>SDU</code> (Service Data Unit / Nutzdaten).</li>\n</ul>"}, {"from": "FIG-7e1068363dfd313a", "to": "FIG-b0bd5dbaada32b7e", "fr": "R3.1.5", "tr": "R3.2.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
